class ValidWordAbbr
{
    unordered_map< string, string>dict;
    string abbr(const string&s)
    {
        if (s.size() <= 2)
        {
            return s;
        }
        return s.substr(0, 1) + to_string(s.size() - 2) + s.back();
    }
public:
    ValidWordAbbr(vector< string>& dictionary)
    {
        for (auto&s : dictionary)
        {
            string k = abbr(s);
            auto it = dict.find(k);
            if (it == dict.end())
            {
                dict[k] = s;
            }
            else if (it->second != s) it->second = "";
        }
    }
    bool isUnique(string word)
    {
        string k = abbr(word);
        auto it = dict.find(k);
        return it == dict.end() || it->second == word;
    }
};
